import{z as l,x as s,o as i,c as p,q as t,j as B,D as E,d as r,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"可理性化","description":"","frontmatter":{"title":"可理性化","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rationalizability.md","filePath":"econ/rationalizability.md","lastUpdated":1791063341000}'),d={name:"econ/rationalizability.md"};function m(D,a,c,F,h,C){const n=s("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="可理性化" tabindex="-1">可理性化 <a class="header-anchor" href="#可理性化" aria-label="Permalink to &quot;可理性化&quot;">​</a></h1><div class="epigraph"><p>共同知识理性所允许的，是那些对「别人也只使用可理性化策略」的某种信念而言的最优反应；它不必已经是相互正确的预期。</p><footer>—— Bernheim, Rationalizable Strategic Behavior, Econometrica, 1984；Pearce, Econometrica, 1984</footer></div><p><a href="/econ/dominance-iesds">上一课</a>用 IESDS 删掉「无论别人怎样都差」的招。缺口是正面刻画：若每人最优化，且这是共同知识，但不必已经猜中别人那一个点，还能玩哪些策略？Bernheim 与 Pearce 的可理性化回答这一问。相互最优反应仍不出场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信念 \\(\\mu_i\\) 是对 \\(s_{-i}\\) 的概率。策略 \\(s_i\\) 是对 \\(\\mu_i\\) 的最优反应，若它在支撑 \\(\\mu_i\\) 的那些 \\(s_{-i}\\) 上不差于任何替代。可理性化集 \\(R=\\prod_i R_i\\) 是满足下列闭包的最大集合：每个 \\(s_i\\in R_i\\) 都是对某个支撑落在 \\(R_{-i}\\) 上的信念的最优反应。也就是说，存在一个无限的「我以为你以为」链条，每层都在优化，从不走出 \\(R\\)。</p><p>两人有限博弈：可理性化 = 相对混合策略的 IESDS。\\(n\\) 人：若允许对对手行动的<strong>相关</strong>猜想，仍与（混合）IESDS 基本重合；若强制独立猜想，集合更瘦。本课主钉允许相关猜想的 Bernheim–Pearce 版本。</p><h3 id="共同知识理性不是已经猜中" tabindex="-1">共同知识理性不是已经猜中 <a class="header-anchor" href="#共同知识理性不是已经猜中" aria-label="Permalink to &quot;共同知识理性不是已经猜中&quot;">​</a></h3><p>猜硬币：两个纯策略都是对「对方出另一面」的最优反应，因而都可理性化；但双方同时猜中并互相最优，纯策略做不到。可理性化允许「我以为你出正面」，哪怕你其实在出反面——只要这个以为在链条上自洽。后课的纳什把「以为」钉成事实。</p><p><span class="marginnote">迭代算法：先删对任何信念都不是最优反应的策略（即被混合严格劣势），再在留下的集合上重复。两人情形与上一课 IESDS 是同一把刀的正反面。\\(n\\) 人相关猜想时，信念可以让对手行动相关，不必是乘积分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限策略式、vNM 支付。计算：迭代删「当前集合上从不最佳应答」的纯策略，直到不动。留下的每个纯策略，都要能指出一个支撑在留下集合里的信念。</p><p>协调博弈：两个纯策略都可理性化，混合也可以。囚徒困境：合作第一轮就不是对任何信念的最优反应（招供严格占优），可理性化只剩招供。这与 IESDS 一致，本课不多给新例子，只改刻画。</p><p><span class="marginnote">直觉类比：把迭代剔除想成「审讯留人」。每一轮，凡讲不出「对手会怎样出招、我为何这么应对才算最优」故事的策略就被请出场；直到留下的每个策略都能讲出一个引用其他在场者的小故事。故事链条可以很长，但每一环都必须是最优反应，不许跳出在场名单。</span></p>',13)),(i(),B(A,null,{default:E(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IESDS%5B%22IESDS%EF%BC%9A%E5%88%A0%E6%97%A0%E8%AE%BA%E6%80%8E%E6%A0%B7%E9%83%BD%E5%B7%AE%22%5D%20--%3E%20RAT%5B%22%E5%8F%AF%E7%90%86%E6%80%A7%E5%8C%96%EF%BC%9A%E5%AF%B9%E6%9F%90%E8%87%AA%E6%B4%BD%E4%BF%A1%E5%BF%B5%E6%9C%80%E4%BC%98%22%5D%0A%20%20RAT%20--%3E%20CKR%5B%22%E5%85%B1%E5%90%8C%E7%9F%A5%E8%AF%86%E7%90%86%E6%80%A7%22%5D%0A%20%20RAT%20--%3E%20NOT%5B%22%E4%BF%A1%E5%BF%B5%E4%B8%8D%E5%BF%85%E7%AD%89%E4%BA%8E%E5%AE%9E%E9%99%85%E7%AD%96%E7%95%A5%22%5D%0A%20%20NOT%20--%3E%20NE%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%8A%8A%E4%BF%A1%E5%BF%B5%E9%92%89%E6%88%90%E4%BA%8B%E5%AE%9E%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"共同知识理性限制的是支持最优反应的信念层级，不是实现哪一个策略组合。链条的每一步都合法，并不强迫所有人的链条接到同一点。因此可理性化集通常是矩形（各人一个策略子集的乘积），里面许多组合「一起发生」时并不相互最优——它们只是各自都能被某段故事说圆。",-1)),a[5]||(a[5]=e("p",null,"与上一课的衔接：严格劣策略对任何信念都不是最优反应，故不可理性化。反复剔除正是在拆那些已经说不圆的层级。可理性化把「还说得圆的」收成一个最大不动集。",-1)),(i(),B(A,null,{default:E(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E8%B5%B7%E7%82%B9%EF%BC%9A%E5%85%A8%E9%83%A8%E7%BA%AF%E7%AD%96%E7%95%A5%E5%9C%A8%E5%9C%BA%22%5D%20--%3E%20DEL%5B%22%E5%88%A0%E5%8E%BB%E5%AF%B9%E4%BB%BB%E4%BD%95%E4%BF%A1%E5%BF%B5%E9%83%BD%E4%B8%8D%E6%98%AF%E6%9C%80%E4%BC%98%E5%8F%8D%E5%BA%94%E7%9A%84%E7%AD%96%E7%95%A5%22%5D%0A%20%20DEL%20--%3E%20S1%5B%22%E5%BE%97%E5%88%B0%E7%BC%A9%E5%B0%8F%E7%9A%84%E9%9B%86%E5%90%88%22%5D%0A%20%20S1%20--%3E%20CHK%7B%22%E5%9C%A8%E7%BC%A9%E5%B0%8F%E9%9B%86%E5%90%88%E4%B8%8A%EF%BC%8C%E8%BF%98%E6%9C%89%E4%BA%BA%E4%B8%8D%E5%86%8D%E6%98%AF%E5%AF%B9%E6%9F%90%E4%BF%A1%E5%BF%B5%E7%9A%84%E6%9C%80%E4%BC%98%E5%8F%8D%E5%BA%94%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20DEL%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20FIX%5B%22%E4%B8%8D%E5%8A%A8%E7%82%B9%EF%BC%9A%E5%8F%AF%E7%90%86%E6%80%A7%E5%8C%96%E9%9B%86%22%5D%0A%20%20FIX%20--%3E%20RECT%5B%22%E9%80%9A%E5%B8%B8%E6%98%AF%E5%90%84%E4%BA%BA%E7%AD%96%E7%95%A5%E5%AD%90%E9%9B%86%E7%9A%84%E4%B9%98%E7%A7%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：容易以为「可理性化集里的组合都会真的发生」。实际上集合是每人一个子集的乘积，像（合作，招供）这样的组合可能躺在集合里，却没有人会一起选它——它只是各方各自的某段信念故事拼起来不矛盾而已。</span></p><h3 id="人相关猜想不是合作" tabindex="-1">\\(n\\) 人相关猜想不是合作 <a class="header-anchor" href="#人相关猜想不是合作" aria-label="Permalink to &quot;$n$ 人相关猜想不是合作&quot;">​</a></h3><p>允许对手行动相关，只是说「我以为他们之间有相关」，不是我们在签可执行合约。相关可以来自我未观察的公共过往。后课相关均衡会把公共随机装置写进解概念；本课的相关只活在某个人的头脑里，还不是大家都服从的信号。</p><p><span class="marginnote">Pearce 同时讨论了「可理性化 + 不使用弱劣」的更小集合。本课用弱版：共同知识理性本身对应严格劣势迭代。弱劣涉及「平手时怎么办」，超出 CKR 的最小含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无限策略、不连续支付，可理性化可以空或难算。不完全信息要先写成类型，再对类型依存策略做可理性化，那是贝叶斯化之后的事。实验里「可理性化预测太宽」是常事：理论给的是逻辑上界，不是选择规则。</p><p>「从不是最优反应」（never a best response）比严格劣势略宽：\\(n\\) 人独立猜想时，有的策略对任何乘积信念都不是最优，却不是被一个混合严格压住。本课允许相关猜想，二者重新对齐，算法才与上一课 IESDS 是同一把刀。</p><p><span class="marginnote">术语翻译：「never a best response」即「无论给对手行动分配什么概率，这个策略的期望支付都排不到第一」。允许相关猜想等于允许对手行动联动，最优反应的候选面变大，策略更容易当上某个信念下的最优，于是删得更少、留下的集合更大。</span></p><p>后课把「信念等于别人真正使用的策略」加成相互最优反应，集合将变瘦，并且不必再是矩形——均衡组合是点（或混合点），不是每人一个子集的乘积。</p><p>后课默认：共同知识理性对应可理性化（两人即 IESDS）；要相互正确预期，才进入纳什。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可理性化是共同知识理性允许的最大策略集。</li><li>每个留下的策略都是对「别人也在该集里」的某信念的最优反应。</li><li>两人与 IESDS 重合；\\(n\\) 人相关猜想保持这一对应。</li><li>信念自洽不必等于信念为真；纳什还在后课。</li><li>出处：Bernheim, <em>Econometrica</em>, 1984；Pearce, <em>Econometrica</em>, 1984。</li></ul>',12))])}const u=l(d,[["render",m]]);export{S as __pageData,u as default};
